{
  "name": "opencode-web-preview",
  "version": "0.1.0",
  "description": "OpenCode Studio companion plugin for managed workspace web previews",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/canxin121/opencode-web-preview.git"
  },
  "homepage": "https://github.com/canxin121/opencode-web-preview",
  "bugs": {
    "url": "https://github.com/canxin121/opencode-web-preview/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "studio",
    "preview",
    "frontend",
    "vite"
  ],
  "publishConfig": {
    "access": "public"
  },
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": {
      "import": "./src/index.ts",
      "types": "./src/index.ts"
    }
  },
  "files": [
    "src",
    "README.md",
    "README.zh-CN.md",
    "DETAIL.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "bunx tsc -p tsconfig.json --noEmit",
    "preview:selfcheck": "bun run src/selfcheck.ts"
  },
  "engines": {
    "bun": ">=1.3.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "*",
    "bun-types": "^1.3.6",
    "typescript": "^5.9.3"
  },
  "license": "MIT"
}
